(73, '단어', '쇼핑', '{"word": "color", "examples": [{"ex_text": "What color is it?", "ex_mean": "그게 무슨 색인가요?"}, {"ex_text": "I like this color.", "ex_mean": "저는 이 색깔이 좋아요."}]}', '색', '/ˈkʌlɚ/', '컬러', '{}'),
(74, '단어', '쇼핑', '{"word": "fitting room", "examples": [{"ex_text": "The fitting room is over there.", "ex_mean": "탈의실은 저쪽에 있습니다."}, {"ex_text": "Can I go to the fitting room?", "ex_mean": "탈의실에 가도 될까요?"}]}', '탈의실', '/ˈfɪtɪŋ ɹum/', '피팅 룸', '{}'),
(75, '단어', '쇼핑', '{"word": "receipt", "examples": [{"ex_text": "Keep your receipt.", "ex_mean": "영수증을 보관하세요."}, {"ex_text": "Can I have a receipt?", "ex_mean": "영수증 좀 주실래요?"}]}', '영수증', '/ɹɪˈsit/', '영수증', '{}'),
(76, '단어', '쇼핑', '{"word": "cash", "examples": [{"ex_text": "I only have cash.", "ex_mean": "저는 현금만 가지고 있어요."}, {"ex_text": "Do you accept cash?", "ex_mean": "현금 받으시나요?"}]}', '현금', '/kæʃ/', '캐시', '{}'),
(77, '단어', '쇼핑', '{"word": "exchange", "examples": [{"ex_text": "I want to exchange this.", "ex_mean": "이거 교환하고 싶어요."}, {"ex_text": "Can I exchange it for a larger size?", "ex_mean": "더 큰 사이즈로 교환할 수 있을까요?"}]}', '교환', '/ɪksˈtʃeɪndʒ/', '교환', '{}'),
(78, '단어', '쇼핑', '{"word": "refund", "examples": [{"ex_text": "Can I get a refund?", "ex_mean": "환불받을 수 있을까요?"}, {"ex_text": "I want a full refund.", "ex_mean": "전액 환불을 원해요."}]}', '환불', '/ˈɹiˌfʌnd/', '환불', '{}'),
(79, '단어', '쇼핑', '{"word": "discount", "examples": [{"ex_text": "Can I get a discount?", "ex_mean": "할인받을 수 있을까요?"}, {"ex_text": "Is there a student discount?", "ex_mean": "학생 할인이 있나요?"}]}', '할인', '/ˈdɪsˌkaʊnt/', '디스카운트', '{}'),
(80, '단어', '쇼핑', '{"word": "credit card", "examples": [{"ex_text": "I will pay by credit card.", "ex_mean": "신용카드로 결제할게요."}, {"ex_text": "Do you take credit cards?", "ex_mean": "신용카드 되나요?"}]}', '신용카드', '/ˈkɹɛdɪt kɑɹd/', '신용카드', '{}'),
(81, '단어', '비즈니스 표현', '{"word": "meeting", "examples": [{"ex_text": "The meeting starts at 10.", "ex_mean": "회의는 10시에 시작합니다."}, {"ex_text": "We have an important meeting.", "ex_mean": "우리는 중요한 회의가 있어요."}]}', '회의', '/ˈmitɪŋ/', '미팅', '{}'),
(82, '단어', '비즈니스 표현', '{"word": "schedule", "examples": [{"ex_text": "What is our schedule?", "ex_mean": "우리 일정이 어떻게 되나요?"}, {"ex_text": "I have a busy schedule.", "ex_mean": "일정이 빡빡해요."}]}', '일정', '/ˈskɛdʒuɫ/', '스케줄', '{}'),
(83, '단어', '비즈니스 표현', '{"word": "deadline", "examples": [{"ex_text": "The deadline is tomorrow.", "ex_mean": "마감은 내일입니다."}, {"ex_text": "We missed the deadline.", "ex_mean": "마감을 놓쳤어요."}]}', '마감일', '/ˈdɛdˌlaɪn/', '데드라인', '{}'),
(84, '단어', '비즈니스 표현', '{"word": "proposal", "examples": [{"ex_text": "Send me the proposal.", "ex_mean": "제안서를 보내주세요."}, {"ex_text": "I am writing a proposal.", "ex_mean": "제안서를 쓰고 있어요."}]}', '제안서', '/pɹəˈpoʊzəl/', '프러포절', '{}'),
(85, '단어', '비즈니스 표현', '{"word": "contract", "examples": [{"ex_text": "Sign the contract here.", "ex_mean": "여기 계약서에 서명하세요."}, {"ex_text": "The contract is very long.", "ex_mean": "계약서가 매우 기네요."}]}', '계약', '/ˈkɑnˌtɹækt/', '컨트랙트', '{}'),
(86, '단어', '비즈니스 표현', '{"word": "client", "examples": [{"ex_text": "The client is coming today.", "ex_mean": "오늘 고객이 오십니다."}, {"ex_text": "We need more clients.", "ex_mean": "더 많은 고객이 필요해요."}]}', '고객', '/ˈklaɪənt/', '클라이언트', '{}'),
(87, '단어', '비즈니스 표현', '{"word": "invoice", "examples": [{"ex_text": "Send the invoice to me.", "ex_mean": "인보이스를 저에게 보내주세요."}, {"ex_text": "Where is the invoice?", "ex_mean": "인보이스가 어디 있나요?"}]}', '송장/청구서', '/ˈɪnˌvɔɪs/', '인보이스', '{}'),
(88, '단어', '비즈니스 표현', '{"word": "budget", "examples": [{"ex_text": "What is the budget?", "ex_mean": "예산이 얼마인가요?"}, {"ex_text": "We are over budget.", "ex_mean": "예산이 초과되었어요."}]}', '예산', '/ˈbʌdʒɪt/', '버짓', '{}'),
(89, '단어', '비즈니스 표현', '{"word": "report", "examples": [{"ex_text": "Write the report now.", "ex_mean": "지금 보고서를 쓰세요."}, {"ex_text": "I read the report.", "ex_mean": "보고서를 읽었어요."}]}', '보고서', '/ɹɪˈpɔɹt/', '리포트', '{}'),
(90, '단어', '비즈니스 표현', '{"word": "update", "examples": [{"ex_text": "Give me an update.", "ex_mean": "업데이트 좀 해주세요."}, {"ex_text": "I am updating the file.", "ex_mean": "파일을 업데이트하고 있어요."}]}', '진행 상황', '/ʌpˈdeɪt/', '업데이트', '{}'),

-- 3. 문장 (91~140)
(91, '문장', '기본표현(일상)', '{"word": "Could you speak slowly?", "examples": [{"ex_text": "I am a beginner. Could you speak slowly?", "ex_mean": "저는 초보예요. 천천히 말씀해 주실래요?"}, {"ex_text": "Could you speak slowly for me?", "ex_mean": "저를 위해 조금만 천천히 말씀해 주시겠어요?"}]}', '천천히 말해주실 수 있나요?', '/kʊd ju spik ˈsloʊli/', '쿠드 유 스피크 슬로울리?', '{}'),
(92, '문장', '기본표현(일상)', '{"word": "Can you repeat that?", "examples": [{"ex_text": "I missed it. Can you repeat that?", "ex_mean": "놓쳤어요. 다시 말해줄래요?"}, {"ex_text": "Can you repeat that more clearly?", "ex_mean": "더 명확하게 다시 말해줄래요?"}]}', '다시 말해줄래요?', '/kæn ju ɹɪˈpit ðæt/', '캔 유 리핏 댓?', '{}'),
(93, '문장', '기본표현(일상)', '{"word": "I don''t understand.", "examples": [{"ex_text": "I''m sorry, I don''t understand.", "ex_mean": "미안해요, 이해가 안 돼요."}, {"ex_text": "I don''t understand this part.", "ex_mean": "이 부분이 이해가 안 돼요."}]}', '이해가 안 돼요.', '/aɪ doʊnt ˌʌndɚˈstænd/', '아이 돈트 언더스탠드.', '{}'),
(94, '문장', '기본표현(일상)', '{"word": "Could you help me, please?", "examples": [{"ex_text": "Excuse me, could you help me, please?", "ex_mean": "실례합니다, 저 좀 도와주실 수 있나요?"}, {"ex_text": "Could you help me with this bag, please?", "ex_mean": "이 가방 좀 도와주실 수 있나요?"}]}', '도와주실 수 있나요?', '/kʊd ju hɛlp mi pliz/', '쿠드 유 헬프 미, 플리즈?', '{}'),
(95, '문장', '기본표현(일상)', '{"word": "I''m sorry, I’m late.", "examples": [{"ex_text": "I am so sorry, I am late for the class.", "ex_mean": "정말 죄송해요, 수업에 늦었어요."}, {"ex_text": "I''m sorry, I am late because of traffic.", "ex_mean": "미안해요, 차가 막혀서 늦었어요."}]}', '미안해요, 늦었어요.', '/aɪm ˈsɑɹi aɪm leɪt/', '아임 쏘리, 아임 레이트.', '{}'),
(96, '문장', '기본표현(일상)', '{"word": "Please say it again.", "examples": [{"ex_text": "I couldn''t hear you. Please say it again.", "ex_mean": "못 들었어요. 다시 말씀해 주세요."}, {"ex_text": "Please say it again one more time.", "ex_mean": "한 번만 더 말씀해 주세요."}]}', '다시 말해 주세요.', '/pliz seɪ ɪt əˈɡɛn/', '플리즈 세이 잇 어게인.', '{}'),
(97, '문장', '기본표현(일상)', '{"word": "What does that mean?", "examples": [{"ex_text": "I don''t know the word. What does that mean?", "ex_mean": "그 단어를 몰라요. 무슨 뜻인가요?"}, {"ex_text": "What does that mean in Korean?", "ex_mean": "그게 한국어로 무슨 뜻인가요?"}]}', '그게 무슨 뜻이에요?', '/wʌt dʌz ðæt min/', '왓 더즈 댓 민?', '{}'),
(98, '문장', '기본표현(일상)', '{"word": "Could you write it down?", "examples": [{"ex_text": "I can''t spell it. Could you write it down?", "ex_mean": "철자를 모르겠어요. 좀 적어주실래요?"}, {"ex_text": "Could you write it down on this paper?", "ex_mean": "이 종이에 좀 적어주실래요?"}]}', '적어주실 수 있나요?', '/kʊd ju ɹaɪt 잇 daʊn/', '쿠드 유 라잇 잇 다운?', '{}'),
(99, '문장', '기본표현(일상)', '{"word": "Let’s talk later.", "examples": [{"ex_text": "I am busy now. Let''s talk later.", "ex_mean": "지금 바빠요. 나중에 이야기해요."}, {"ex_text": "Let''s talk later about the project.", "ex_mean": "그 프로젝트에 대해선 나중에 이야기해요."}]}', '나중에 이야기해요.', '/lɛts tɔk ˈleɪtɚ/', '렛츠 톡 레이터.', '{}'),
(100, '문장', '기본표현(일상)', '{"word": "Is this the right way?", "examples": [{"ex_text": "Excuse me, is this the right way to the museum?", "ex_mean": "실례합니다, 박물관 가는 이 길이 맞나요?"}, {"ex_text": "I am lost. Is this the right way?", "ex_mean": "길을 잃었어요. 이 길이 맞나요?"}]}', '이 길이 맞나요?', '/ɪz ðɪs ðə ɹaɪt weɪ/', '이즈 디스 더 라잇 웨이?', '{}'),
(101, '문장', '여행', '{"word": "Where is the airport?", "examples": [{"ex_text": "Where is the airport limousine bus stop?", "ex_mean": "공항 리무진 버스 정류장이 어디예요?"}, {"ex_text": "Where is the nearest airport?", "ex_mean": "가장 가까운 공항이 어디인가요?"}]}', '공항이 어디예요?', '/wɛɹ ɪz ði ˈɛɹˌpɔɹt/', '웨어 이즈 디 에어포트?', '{}'),
(102, '문장', '여행', '{"word": "I have a reservation.", "examples": [{"ex_text": "I have a reservation under the name of Kim.", "ex_mean": "김씨 이름으로 예약이 되어 있습니다."}, {"ex_text": "I have a reservation for two people.", "ex_mean": "두 명 예약했습니다."}]}', '예약이 있어요.', '/aɪ hæv ə ˌɹɛzɚˈveɪʃən/', '아이 해브 어 레저베이션.', '{}'),
(103, '문장', '여행', '{"word": "Where is gate A3?", "examples": [{"ex_text": "Excuse me, where is gate A3?", "ex_mean": "실례합니다, A3 게이트가 어디인가요?"}, {"ex_text": "Can you tell me where is gate A3?", "ex_mean": "A3 게이트가 어디인지 알려주실래요?"}]}', 'A3 탑승구가 어디예요?', '/wɛɹ ɪz ɡeɪt eɪ θɹi/', '웨어 이즈 게이트 에이 쓰리?', '{}'),
(104, '문장', '여행', '{"word": "May I see your passport?", "examples": [{"ex_text": "For identification, may I see your passport?", "ex_mean": "본인 확인을 위해 여권을 좀 볼 수 있을까요?"}, {"ex_text": "May I see your passport and ticket?", "ex_mean": "여권과 티켓을 보여주시겠어요?"}]}', '여권을 보여주시겠어요?', '/meɪ aɪ si jʊɹ ˈpæsˌpɔɹt/', '메이 아이 씨 유어 패스포트?', '{}'),
(105, '문장', '여행', '{"word": "How much is a ticket?", "examples": [{"ex_text": "How much is a ticket to Seoul?", "ex_mean": "서울행 티켓이 얼마예요?"}, {"ex_text": "How much is a ticket for an adult?", "ex_mean": "성인용 티켓은 얼마인가요?"}]}', '표가 얼마예요?', '/haʊ mʌtʃ ɪz ə ˈtɪkɪt/', '하우 머치 이즈 어 티켓?', '{}'),
(106, '문장', '여행', '{"word": "Where is the check-in counter?", "examples": [{"ex_text": "Where is the check-in counter for Korean Air?", "ex_mean": "대한항공 체크인 카운터가 어디인가요?"}, {"ex_text": "Excuse me, where is the check-in counter?", "ex_mean": "실례합니다, 체크인 카운터가 어디예요?"}]}', '체크인 카운터가 어디예요?', '/wɛɹ ɪz ðə ˈtʃɛk ɪn ˈkaʊntɚ/', '웨어 이즈 더 체크인 카운터?', '{}'),
(107, '문장', '여행', '{"word": "My luggage is heavy.", "examples": [{"ex_text": "Can you help me? My luggage is heavy.", "ex_mean": "좀 도와주실래요? 제 짐이 무거워요."}, {"ex_text": "My luggage is heavy, I need a cart.", "ex_mean": "짐이 무거워서 카트가 필요해요."}]}', '제 짐이 무거워요.', '/maɪ ˈlʌɡɪdʒ ˈhɛvi/', '마이 러기지 이즈 헤비.', '{}'),
(108, '문장', '여행', '{"word": "How do I get to the station?", "examples": [{"ex_text": "How do I get to the station by bus?", "ex_mean": "버스로 역까지 어떻게 가나요?"}, {"ex_text": "How do I get to the station from here?", "ex_mean": "여기서 역까지 어떻게 가나요?"}]}', '역에 어떻게 가요?', '/haʊ du aɪ ɡɛt tə ðə ˈsteɪʃən/', '하우 두 아이 겟 투 더 스테이션?', '{}'),
(109, '문장', '여행', '{"word": "Can you show me on the map?", "examples": [{"ex_text": "I am lost. Can you show me on the map?", "ex_mean": "길을 잃었어요. 지도에서 보여주실래요?"}, {"ex_text": "Can you show me where the museum is on the map?", "ex_mean": "박물관이 어디인지 지도에서 보여주실래요?"}]}', '지도에서 보여주실래요?', '/kæn ju ʃoʊ mi ɑn ðə mæp/', '캔 유 쇼 미 온 더 맵?', '{}'),
(110, '문장', '여행', '{"word": "I''d like to go sightseeing.", "examples": [{"ex_text": "I''d like to go sightseeing tomorrow.", "ex_mean": "내일 관광하고 싶어요."}, {"ex_text": "I''d like to go sightseeing in the city center.", "ex_mean": "시내 중심가를 관광하고 싶어요."}]}', '관광하고 싶어요.', '/aɪd laɪk tə ɡoʊ ˈsaɪtˌsiɪŋ/', '아이드 라익 투 고 사이트씨잉.', '{}'),
(111, '문장', '음식', '{"word": "Could I see the menu?", "examples": [{"ex_text": "Excuse me, could I see the menu, please?", "ex_mean": "실례합니다, 메뉴판 좀 보여주실래요?"}, {"ex_text": "Could I see the menu once more?", "ex_mean": "메뉴판 한 번 더 볼 수 있을까요?"}]}', '메뉴 좀 볼 수 있을까요?', '/kʊd aɪ si ðə ˈmɛnju/', '쿠드 아이 씨 더 메뉴?', '{}'),
(112, '문장', '음식', '{"word": "I''d like water, please.", "examples": [{"ex_text": "I''d like cold water, please.", "ex_mean": "찬물 좀 주세요."}, {"ex_text": "I''d like water, please, without ice.", "ex_mean": "얼음 없이 물 좀 주세요."}]}', '물 주세요.', '/aɪd laɪk ˈwɔtɚ pliz/', '아이드 라익 워터, 플리즈.', '{}'),
(113, '문장', '음식', '{"word": "Two teas, please.", "examples": [{"ex_text": "Two black teas, please.", "ex_mean": "홍차 두 잔 주세요."}, {"ex_text": "Two teas, please, one hot and one cold.", "ex_mean": "차 두 잔 주세요, 하나는 뜨거운 거 하나는 찬 거요."}]}', '차 두 잔 주세요.', '/tu tiz pliz/', '투 티즈, 플리즈.', '{}'),
(114, '문장', '음식', '{"word": "Is this dish spicy?", "examples": [{"ex_text": "Is this dish spicy for kids?", "ex_mean": "이 요리 아이들이 먹기에 매운가요?"}, {"ex_text": "Is this dish spicy or mild?", "ex_mean": "이 요리 매운가요, 아니면 순한가요?"}]}', '이 요리 매워요?', '/ɪz ðɪs dɪʃ ˈspaɪsi/', '이즈 디스 디쉬 스파이시?', '{}'),
(115, '문장', '음식', '{"word": "I''m vegetarian.", "examples": [{"ex_text": "I can''t eat meat. I''m vegetarian.", "ex_mean": "고기를 못 먹어요. 저는 채식주의자예요."}, {"ex_text": "Do you have any options for me? I''m vegetarian.", "ex_mean": "저를 위한 옵션이 있나요? 저는 채식주의자예요."}]}', '저는 채식이에요.', '/aɪm ˌvɛdʒəˈtɛɹiən/', '아임 베지테리언.', '{}'),
(116, '문장', '음식', '{"word": "Can I have some bread?", "examples": [{"ex_text": "I''m hungry. Can I have some bread?", "ex_mean": "배고파요. 빵 좀 주실래요?"}, {"ex_text": "Can I have some bread with butter?", "ex_mean": "버터를 곁들인 빵 좀 주실래요?"}]}', '빵 좀 주실래요?', '/kæn aɪ hæv sʌm bɹɛd/', '캔 아이 해브 썸 브레드?', '{}'),
(117, '문장', '음식', '{"word": "I want chicken and rice.", "examples": [{"ex_text": "I want chicken and rice for dinner.", "ex_mean": "저녁으로 치킨이랑 밥을 먹고 싶어요."}, {"ex_text": "I want chicken and rice, please.", "ex_mean": "치킨이랑 밥 주세요."}]}', '치킨이랑 밥이 먹고 싶어요.', '/aɪ wɑnt ˈtʃɪkɪn ænd ɹaɪs/', '아이 원트 치킨 앤 라이스.', '{}'),
(118, '문장', '음식', '{"word": "Could you make it less spicy?", "examples": [{"ex_text": "It looks spicy. Could you make it less spicy?", "ex_mean": "매워 보여요. 덜 맵게 해주실 수 있나요?"}, {"ex_text": "Could you make it less spicy, please?", "ex_mean": "덜 맵게 해주실 수 있나요, 제발?"}]}', '덜 맵게 해주실 수 있나요?', '/kʊd ju meɪk 잇 lɛs ˈspaɪsi/', '쿠드 유 메익 잇 레스 스파이시?', '{}'),
(119, '문장', '음식', '{"word": "Can we get the check, please?", "examples": [{"ex_text": "We are done. Can we get the check, please?", "ex_mean": "다 먹었어요. 계산서 좀 주시겠어요?"}, {"ex_text": "Excuse me, can we get the check, please?", "ex_mean": "실례합니다, 계산서 좀 주시겠어요?"}]}', '계산서 주세요.', '/kæn wi ɡɛt ðə tʃɛk pliz/', '캔 위 겟 더 첵, 플리즈?', '{}'),
(120, '문장', '음식', '{"word": "I''d like dessert, please.", "examples": [{"ex_text": "I''d like dessert, please. What do you have?", "ex_mean": "후식 주세요. 어떤 것이 있나요?"}, {"ex_text": "I''d like dessert, please, with coffee.", "ex_mean": "커피와 함께 후식 주세요."}]}', '후식 주세요.', '/aɪd laɪk dɪˈzɝt pliz/', '아이드 라익 디저트, 플리즈.', '{}'),
(121, '문장', '쇼핑', '{"word": "How much is this?", "examples": [{"ex_text": "How much is this shirt?", "ex_mean": "이 셔츠 얼마예요?"}, {"ex_text": "I like this, how much is this?", "ex_mean": "이거 마음에 드는데, 얼마인가요?"}]}', '이거 얼마예요?', '/haʊ mʌtʃ ɪz ðɪs/', '하우 머치 이즈 디스?', '{}'),
(122, '문장', '쇼핑', '{"word": "Is this on sale?", "examples": [{"ex_text": "It is cheap. Is this on sale?", "ex_mean": "저렴하네요. 이거 할인 중인가요?"}, {"ex_text": "Is this on sale until today?", "ex_mean": "이거 오늘까지 할인인가요?"}]}', '이거 할인 중인가요?', '/ɪz ðɪs ɑn seɪl/', '이즈 디스 온 세일?', '{}'),
(123, '문장', '쇼핑', '{"word": "Do you have this in another color?", "examples": [{"ex_text": "I don''t like red. Do you have this in another color?", "ex_mean": "빨간색은 싫어요. 다른 색 있나요?"}, {"ex_text": "It is beautiful. Do you have this in another color?", "ex_mean": "아름답네요. 다른 색도 있나요?"}]}', '다른 색 있어요?', '/du ju hæv ðɪs ɪn əˈnʌðɚ ˈkʌlɚ/', '두 유 해브 디스 인 어나더 컬러?', '{}'),
(124, '문장', '쇼핑', '{"word": "Can I try it on?", "examples": [{"ex_text": "I like this style. Can I try it on?", "ex_mean": "이 스타일 마음에 들어요. 입어봐도 될까요?"}, {"ex_text": "It looks small. Can I try it on?", "ex_mean": "작아 보이네요. 입어봐도 될까요?"}]}', '입어봐도 될까요?', '/kæn aɪ tɹaɪ 잇 ɑn/', '캔 아이 트라이 잇 온?', '{}'),
(125, '문장', '쇼핑', '{"word": "Where is the fitting room?", "examples": [{"ex_text": "Excuse me, where is the fitting room?", "ex_mean": "실례합니다, 탈의실이 어디예요?"}, {"ex_text": "Where is the fitting room for men?", "ex_mean": "남성용 탈의실은 어디인가요?"}]}', '탈의실이 어디예요?', '/wɛɹ ɪz ðə ˈfɪtɪŋ ɹum/', '웨어 이즈 더 피팅 룸?', '{}'),
(126, '문장', '쇼핑', '{"word": "Do you have any discount?", "examples": [{"ex_text": "It is expensive. Do you have any discount?", "ex_mean": "비싸네요. 할인되나요?"}, {"ex_text": "Do you have any discount for members?", "ex_mean": "회원 할인이 있나요?"}]}', '할인 있나요?', '/du ju hæv ˈɛni ˈdɪsˌkaʊnt/', '두 유 해브 애니 디스카운트?', '{}'),
(127, '문장', '쇼핑', '{"word": "I''ll pay with a credit card.", "examples": [{"ex_text": "I don''t have cash. I''ll pay with a credit card.", "ex_mean": "현금이 없어요. 신용카드로 결제할게요."}, {"ex_text": "I''ll pay with a credit card, please.", "ex_mean": "신용카드로 결제하겠습니다."}]}', '신용카드로 결제할게요.', '/aɪl peɪ wɪð ə ˈkɹɛdɪt kɑɹd/', '아일 페이 위드 어 크레딧 카드.', '{}'),
(128, '문장', '쇼핑', '{"word": "Can I get a receipt?", "examples": [{"ex_text": "Can I get a receipt for my purchase?", "ex_mean": "구매 영수증 좀 받을 수 있을까요?"}, {"ex_text": "Can I get a receipt, please?", "ex_mean": "영수증 좀 주실래요?"}]}', '영수증 받을 수 있나요?', '/kæn aɪ ɡɛt ə ɹɪˈsit/', '캔 아이 겟 어 리싯?', '{}'),
(129, '문장', '쇼핑', '{"word": "I''d like to exchange this.", "examples": [{"ex_text": "The size is wrong. I''d like to exchange this.", "ex_mean": "사이즈가 안 맞아요. 교환하고 싶어요."}, {"ex_text": "I''d like to exchange this for a new one.", "ex_mean": "새것으로 교환하고 싶어요."}]}', '이거 교환하고 싶어요.', '/aɪd laɪk tə ɪksˈtʃeɪndʒ ðɪs/', '아이드 라익 투 익스체인지 디스.', '{}'),
(130, '문장', '쇼핑', '{"word": "Can I get a refund?", "examples": [{"ex_text": "It is broken. Can I get a refund?", "ex_mean": "고장 났어요. 환불 가능할까요?"}, {"ex_text": "Can I get a refund? I have the receipt.", "ex_mean": "환불 가능할까요? 영수증 있어요."}]}', '환불 가능할까요?', '/kæn aɪ ɡɛt ə ˈɹiˌfʌnd/', '캔 아이 겟 어 리펀드?', '{}'),
(131, '문장', '비즈니스 표현', '{"word": "Let''s schedule a meeting.", "examples": [{"ex_text": "I have something to discuss. Let''s schedule a meeting.", "ex_mean": "논의할 것이 있어요. 회의 일정을 잡죠."}, {"ex_text": "Let''s schedule a meeting for next Monday.", "ex_mean": "다음 주 월요일로 회의 일정을 잡죠."}]}', '회의 일정을 잡죠.', '/lɛts ˈskɛdʒuɫ ə ˈmitɪŋ/', '렛츠 스케줄 어 미팅.', '{}'),
(132, '문장', '비즈니스 표현', '{"word": "What''s the deadline?", "examples": [{"ex_text": "When should I finish? What''s the deadline?", "ex_mean": "언제까지 끝내야 하나요? 마감이 언제죠?"}, {"ex_text": "What''s the deadline for this task?", "ex_mean": "이 업무의 마감일이 언제인가요?"}]}', '마감이 언제인가요?', '/wʌts ðə ˈdɛdˌlaɪn/', '왓츠 더 데드라인?', '{}'),
(133, '문장', '비즈니스 표현', '{"word": "Please send the proposal.", "examples": [{"ex_text": "I want to review it. Please send the proposal.", "ex_mean": "검토하고 싶어요. 제안서를 보내주세요."}, {"ex_text": "Please send the proposal by email.", "ex_mean": "제안서를 이메일로 보내주세요."}]}', '제안서를 보내주세요.', '/pliz sɛnd ðə pɹəˈpoʊzəl/', '플리즈 센드 더 프러포절.', '{}'),
(134, '문장', '비즈니스 표현', '{"word": "We need to review the contract.", "examples": [{"ex_text": "Before signing, we need to review the contract.", "ex_mean": "서명하기 전에, 계약서를 검토해야 해요."}, {"ex_text": "We need to review the contract with the lawyer.", "ex_mean": "변호사와 함께 계약서를 검토해야 해요."}]}', '계약서를 검토해야 해요.', '/wi nid tə ɹɪˈvju ðə ˈkɑnˌtɹækt/', '위 니드 투 리뷰 더 컨트랙트.', '{}'),
(135, '문장', '비즈니스 표현', '{"word": "I''ll contact the client.", "examples": [{"ex_text": "The issue is resolved. I''ll contact the client.", "ex_mean": "문제가 해결됐어요. 고객에게 연락할게요."}, {"ex_text": "I''ll contact the client right away.", "ex_mean": "당장 고객에게 연락할게요."}]}', '고객에게 연락할게요.', '/aɪl ˈkɑnˌtækt ðə ˈklaɪənt/', '아일 컨택 더 클라이언트.', '{}'),
(136, '문장', '비즈니스 표현', '{"word": "Can you send the invoice?", "examples": [{"ex_text": "I need to pay. Can you send the invoice?", "ex_mean": "지불해야 해요. 송장 좀 보내주실래요?"}, {"ex_text": "Can you send the invoice to our department?", "ex_mean": "저희 부서로 송장 보내주실래요?"}]}', '송장 보내주실래요?', '/kæn ju sɛnd ði ˈɪnˌvɔɪs/', '캔 유 센드 디 인보이스?', '{}'),
(137, '문장', '비즈니스 표현', '{"word": "Our budget is limited.", "examples": [{"ex_text": "We can''t spend more. Our budget is limited.", "ex_mean": "더 쓸 수 없어요. 예산이 한정적이에요."}, {"ex_text": "Our budget is limited for this project.", "ex_mean": "이 프로젝트를 위한 예산이 제한적이에요."}]}', '예산이 제한적이에요.', '/aʊɹ ˈbʌdʒɪt ɪz ˈlɪmɪtɪd/', '아워 버짓 이즈 리미티드.', '{}'),
(138, '문장', '비즈니스 표현', '{"word": "Could you share the report?", "examples": [{"ex_text": "I missed the session. Could you share the report?", "ex_mean": "세션을 놓쳤어요. 보고서 좀 공유해주실래요?"}, {"ex_text": "Could you share the report with the team?", "ex_mean": "팀원들과 보고서 공유해주실 수 있나요?"}]}', '보고서 공유해주실 수 있나요?', '/kʊd ju ʃɛɹ ðə ɹɪˈpɔɹt/', '쿠드 유 쉐어 더 리포트?', '{}'),
(139, '문장', '비즈니스 표현', '{"word": "Can you give me an update?", "examples": [{"ex_text": "How is it going? Can you give me an update?", "ex_mean": "어떻게 돼가나요? 진행 상황 좀 알려줄래요?"}, {"ex_text": "Can you give me an update on the progress?", "ex_mean": "진척 사항에 대해 업데이트 좀 해줄래요?"}]}', '진행 상황 알려주실래요?', '/kæn ju ɡɪv mi ən ʌpˈdeɪt/', '캔 유 기브 미 언 업데이트?', '{}'),
(140, '문장', '비즈니스 표현', '{"word": "Let''s follow up tomorrow.", "examples": [{"ex_text": "Good work today. Let''s follow up tomorrow.", "ex_mean": "오늘 고생했어요. 내일 이어서 확인하죠."}, {"ex_text": "Let''s follow up tomorrow morning.", "ex_mean": "내일 아침에 다시 확인합시다."}]}', '내일 후속으로 확인하죠.', '/lɛts ˈfɑloʊˌʌp təˈmɑɹoʊ/', '렛츠 팔로업 투모로우.', '{}');